const PROGRAMS_CSS=".k-layout>div{min-width:0}
.pg-head{margin:0 0 14px}.pg-head h2{margin:0;font-size:20px}
.pg-h3{font-size:16px;margin:22px 0 10px}.pg-h4{font-size:14px;margin:16px 0 8px}
.pg-card{margin:0 0 14px}.pg-card-head{margin:0 0 8px}.pg-card-head h3{margin:0;font-size:16px}
.pg-flush{padding:0;overflow:hidden;margin:0 0 14px}
.pg-sub{display:block;font-size:13px;color:#56696e;overflow-wrap:anywhere}
.pg-link{border:0;background:none;padding:2px 0;min-height:32px;font:inherit;font-weight:650;color:var(--k-ink);text-align:left;cursor:pointer;text-decoration:underline;text-decoration-color:var(--k-line);text-underline-offset:3px}
.pg-partial{color:var(--k-warning);margin:0 0 12px}
.pg-filters{margin:0 0 12px}.pg-filters input[type=search]{min-height:40px;border:1px solid var(--k-line);border-radius:var(--k-radius-small);padding:0 10px;background:var(--k-paper);min-width:0;width:min(220px,100%)}
.pg-end{justify-content:flex-end;margin-top:14px}.pg-menu{border-top:1px solid var(--k-line);margin-top:16px;padding-top:12px}
.pg-two{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(min(340px,100%),1fr));margin:0 0 14px}.pg-two>.pg-card{margin:0}
.pg-stats{margin:0 0 14px}.pg-cards{margin:0 0 14px}
.pg-hero{margin:0 0 14px}.pg-hero-text{font-size:18px;margin:4px 0}
.pg-pcard h3,.pg-gate h3{margin:0;font-size:16px}.pg-pcard .pg-sub,.pg-gate .pg-sub{margin:4px 0 8px}
.pg-dl{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;margin:8px 0;font-size:14px}.pg-dl dt{color:#56696e}.pg-dl dd{margin:0;overflow-wrap:anywhere}
.pg-list{list-style:none;margin:0;padding:0}.pg-list li{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:8px 0;border-bottom:1px solid var(--k-line)}.pg-list li:last-child{border-bottom:0}
.pg-checks{list-style:none;margin:6px 0 10px;padding:0}.pg-checks li{padding:3px 0;font-size:14px}
.pg-crit{list-style:none;margin:0 0 8px;padding:0}.pg-crit li{display:flex;gap:12px;flex-wrap:wrap;padding:7px 0;border-bottom:1px solid var(--k-line);font-size:14px}
.pg-green{background:var(--k-soft);color:var(--k-accent-strong)}.pg-amber{background:var(--k-warning-soft);color:var(--k-warning)}.pg-red{background:var(--k-danger-soft);color:var(--k-danger)}.pg-blue{background:#e8f0fb;color:#1f4f8a}.pg-grey{background:#eef1f0;color:#3d4f53}
.pg-form{display:grid;gap:0 12px;grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr))}.pg-wide{grid-column:1/-1}
.pg-form select,.pg-form input,.pg-form textarea,.pg-callout select,.pg-callout input,.k-panel .k-field input,.k-panel .k-field select,.k-panel .k-field textarea,.pg-card .k-field textarea{width:100%}
.k-field select+select{margin-top:6px}
.pg-callout{background:var(--k-warning-soft);border-radius:var(--k-radius-small);padding:10px 12px;margin:8px 0}.pg-callout p{margin:0 0 8px}
.pg-check{display:flex;gap:8px;align-items:center;min-height:36px;font-size:14px}
.pg-pair{display:flex;gap:4px}.pg-pair .k-cell{min-width:80px}
.pg-report{white-space:pre-wrap;font-size:14px;background:var(--k-light);border:1px solid var(--k-line);border-radius:var(--k-radius-small);padding:12px;overflow-wrap:anywhere}
.pg-mono{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px}
.pg-a{display:inline-flex;align-items:center;text-decoration:none}
.pg-matrix{display:grid;grid-template-columns:auto repeat(3,minmax(0,1fr));gap:6px;max-width:520px}.pg-ax{font-size:12px;color:var(--k-muted);display:flex;align-items:center;justify-content:center;text-align:center;padding:2px}
.pg-cellbtn{min-height:52px;border-radius:9px;border:2px solid transparent;font:inherit;font-size:18px;font-weight:750;cursor:pointer}.pg-cellbtn.s1{background:#eef1f0;color:#3d4f53}.pg-cellbtn.s2{background:var(--k-warning-soft);color:var(--k-warning)}.pg-cellbtn.s3{background:var(--k-danger-soft);color:var(--k-danger)}.pg-cellbtn[aria-pressed=true]{border-color:var(--k-ink)}
.pg-gantt-wrap{overflow-x:auto;max-width:100%}.pg-gantt{position:relative;font-size:13px}
.pg-g-head,.pg-g-row,.pg-g-lane{display:grid;grid-template-columns:var(--lw,230px) minmax(0,1fr)}
.pg-g-head{background:var(--k-light);border-bottom:1px solid var(--k-line)}.pg-g-head .pg-g-label{font-size:12px;font-weight:700;color:var(--k-muted);padding:8px 12px}
.pg-g-axis{position:relative;height:34px}.pg-g-axis span{position:absolute;top:0;height:34px;border-left:1px solid var(--k-line);padding:8px 6px;font-size:12px;color:var(--k-muted);white-space:nowrap}
.pg-g-label{position:sticky;left:0;z-index:2;background:var(--k-paper);border-right:1px solid var(--k-line);padding:6px 10px;min-width:0;overflow-wrap:anywhere}.pg-g-label b{display:block;font-size:13px}
.pg-g-lane .pg-g-label,.pg-g-lane .pg-g-track{background:#f1f5f3;font-weight:700;font-size:12px;color:var(--k-ink)}.pg-g-lane.program .pg-g-label,.pg-g-lane.program .pg-g-track{background:var(--k-soft);font-size:13px}
.pg-g-row{border-bottom:1px solid var(--k-line);min-height:46px}.pg-g-row.dim{opacity:.55}
.pg-g-track{position:relative;min-height:28px}.pg-g-grid{position:absolute;top:0;bottom:0;border-left:1px solid #eef2f0}
.pg-bar,.pg-diamond{position:absolute;border:0;padding:0;cursor:pointer}
.pg-bar{top:13px;height:18px;border-radius:5px;background:#7fb8a6;min-width:6px}.pg-bar.done{background:#9aa6a9}.pg-bar.at_risk{background:#c99a3c}.pg-bar.cancelled{background:#ccd3d1}.pg-bar.crit{background:var(--k-accent);box-shadow:0 0 0 2px var(--k-paper),0 0 0 4px #0a806566}
.pg-bar.drive,.pg-diamond.drive{outline:3px solid #e0a526;outline-offset:2px}
.pg-ghost{position:absolute;top:34px;height:6px;border-radius:3px;background:repeating-linear-gradient(90deg,#a9b6b2 0 6px,transparent 6px 10px);pointer-events:none}
.pg-diamond{top:14px;width:18px;height:18px;margin-left:-9px;transform:rotate(45deg);background:#7fb8a6;border:2px solid var(--k-paper);box-shadow:0 0 0 1px #5b8f80}.pg-diamond.key{background:var(--k-ink)}.pg-diamond.crit{background:var(--k-accent);box-shadow:0 0 0 2px var(--k-accent-strong)}.pg-diamond.done{background:#9aa6a9}.pg-diamond.cancelled{background:#ccd3d1}
.pg-today{position:absolute;top:0;bottom:0;width:0;border-left:2px dashed var(--k-danger);pointer-events:none}
.pg-legend{display:flex;flex-wrap:wrap;gap:6px 16px;color:var(--k-muted);padding:10px 14px}.pg-legend span{display:inline-flex;align-items:center;gap:6px}
.pg-legend i{display:inline-block;width:18px;height:9px;border-radius:3px;background:#7fb8a6}.pg-legend i.crit{background:var(--k-accent)}.pg-legend i.ghost{height:5px;background:repeating-linear-gradient(90deg,#a9b6b2 0 5px,transparent 5px 8px)}.pg-legend i.dia{width:10px;height:10px;transform:rotate(45deg);background:var(--k-ink);border-radius:1px}.pg-legend i.today{width:0;height:12px;border-left:2px dashed var(--k-danger);border-radius:0;background:none}.pg-legend i.drive{background:var(--k-paper);outline:2px solid #e0a526}
.k-board-card .pg-link{display:block}
.k-pill{white-space:nowrap}.pg-table .k-table td:first-child{min-width:min(210px,100%)}.pg-table .k-cell[type=date]{min-width:140px}
@container (min-width:721px){.pg-table .k-table td{overflow-wrap:normal}.pg-table .k-table td:first-child .pg-link,.pg-table .k-table td:first-child .pg-sub{min-width:170px}}
.pg-stats{grid-template-columns:repeat(auto-fit,minmax(min(150px,100%),1fr))}
